        cur=l[1:]; seqs[cur]=''
    else:
        seqs[cur]+=l.strip().upper()
inp=seqs['input']
j=215
def rc(s): return ''.join({'A':'T','T':'A','C':'G','G':'C'}[b] for b in s[::-1])
def tm(s):
    r=subprocess.run(['oligotm','-tp','1','-sc','1','-mv','50','-dv','2','-n','0.8','-d','500',s],capture_output=True,text=True)
    return float(r.stdout.strip())
print("FW anneal (downstream top strand):")
for L in range(15,46):
    s=inp[j:j+L]
    print(L, s, round(tm(s),2))
print()
print("REV anneal primer seq (RC of upstream):")
for L in range(15,46):
    up=inp[j-L:j]
    p=rc(up)
    print(L, up, "->", p, round(tm(p),2))
